const root=process.cwd(),names=['labels.csv','layout.svg','manual.txt'];
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const read=p=>{const b=fs.readFileSync(path.join(root,p));return {buffer:b,bytes:b.length,sha256:sha(b)};};
const inventory=JSON.parse(read('handoff/verification.json').buffer.toString('utf8'));
assert.deepEqual(Object.keys(inventory).sort(),['files','summary']);assert(Array.isArray(inventory.files));assert.equal(inventory.files.length,3);
const fields=['path','source_bytes','source_sha256','staged_bytes','staged_sha256','status'].sort();
const actualFiles=names.map((name,index)=>{const record=inventory.files[index],source=read('source-pack/'+name),staged=read('staged-pack/'+name);assert(source.buffer.equals(staged.buffer),'Raw-byte mismatch: '+name);assert.deepEqual(Object.keys(record).sort(),fields);assert.equal(record.path,name);for(const count of [record.source_bytes,record.staged_bytes])assert(Number.isSafeInteger(count)&&count>=0);for(const hash of [record.source_sha256,record.staged_sha256])assert.match(hash,/"'^[0-9a-f]{64}$/);const actual={path:name,source_bytes:source.bytes,source_sha256:source.sha256,staged_bytes:staged.bytes,staged_sha256:staged.sha256,status:'"'matching'};assert.deepEqual(record,actual);return actual;});
assert.deepEqual(inventory.summary,{expected_files:3,present_files:3,matching_files:3,mismatched_files:0,missing_files:0});
for(const count of Object.values(inventory.summary))assert(Number.isSafeInteger(count));
for(const entry of before.filter(f=>f.path"'!=='"'staged-pack/labels.csv')){const after=read(entry.path);assert.equal(after.bytes,entry.bytes,'Protected size changed: '+entry.path);assert.equal(after.sha256,entry.sha256,'Protected digest changed: '+entry.path);}
assert.notEqual(read('staged-pack/labels.csv').sha256,before.find(f=>f.path==='staged-pack/labels.csv').sha256);
const initial=JSON.parse(read('audit/inventory.json').buffer.toString('utf8'));assert.deepEqual(initial.files.map(f=>f.status),['mismatched','missing','matching']);for(let i=0;i<3;i++){assert.equal(initial.files[i].source_bytes,actualFiles[i].source_bytes);assert.equal(initial.files[i].source_sha256,actualFiles[i].source_sha256);}
const walk=dir=>fs.readdirSync(path.join(root,dir),{withFileTypes:true}).flatMap(entry=>{const p=dir?dir+'/'+entry.name:entry.name;assert("'!entry.isSymbolicLink(),'"'Unexpected link: '+p);return entry.isDirectory()?walk(p):[p];});
const added=['staged-pack/layout.svg','handoff/verification.json','handoff/restore-guide.md'];assert.deepEqual(walk('').sort(),[...before.map(f=>f.path),...added].sort());
process.stdout.write(JSON.stringify({result:'passed',exact_inventory_schema:true,source_staged_full_bytes_equal:true,summary:inventory.summary,unchanged_existing_files:before.length-1,only_changed_existing_file:'staged-pack/labels.csv',only_added_files:added,initial_audit_preserved:true,restore_rehearsal_run:false},null,2)+'\\n');
